"""Package local native creature review and a no-autoplay audio listening desk."""
import argparse
import html
import json
from pathlib import Path
import shutil

ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('--workspace',type=Path,required=True);args=p.parse_args()
creatures=args.workspace/'build/local-damp-creatures-v1'
audio=args.workspace/'build/local-damp-audio-v1'
css='''body{margin:0;background:#10181b;color:#ddd4bf;font:16px/1.6 system-ui}main{max-width:1400px;margin:auto;padding:32px}h1,h2,h3{font-family:Georgia,serif;color:#cfb17d}a{color:#d5b884}header{padding-bottom:20px;border-bottom:1px solid #7e6948}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:20px}article{border:1px solid #53605b;background:#162126;padding:16px}img{display:block;width:100%;height:auto}button,select{background:#27312f;color:#eee3cb;border:1px solid #937b50;padding:10px;font:inherit;margin:4px}small{color:#aebbb8}audio{width:100%}.tools{position:sticky;top:0;background:#10181bf5;padding:10px;z-index:2}details{margin:12px 0}summary{cursor:pointer}p{max-width:1000px}table{border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid #53605b;padding:8px}'''
def read(path):return json.loads(path.read_text(encoding='utf-8'))
def shell(title,body):return f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{css}</style><main>{body}</main></html>'
catalog=read(ROOT/'art/enemies/damp-creatures-v1/catalog.json');report=read(creatures/'native/validation.json')
assert not report['failures'],report['failures']
for capture in report['captures']:assert (creatures/'native'/capture).is_file(),capture
(creatures/'concepts').mkdir(exist_ok=True)
cards=[]
for row in catalog['assets']:
    ident=row['id'];shutil.copy2(ROOT/f'art/concepts/damp-creatures-v1/{ident}.png',creatures/f'concepts/{ident}.png')
    options=''.join(f'<option value="native/{ident}-{view}.png">{view.replace("-"," ")}</option>' for view in ['three-quarter','front','side',*row['clips'],*[f'{pose}-{width}' for width in [1278,844,667] for pose in ['idle','attack','fall']]])
    cards.append(f'''<article><h2>{ident.replace('-',' ').title()}</h2><a class="shot" href="native/{ident}-three-quarter.png"><img loading="lazy" src="native/{ident}-three-quarter.png" alt="Actual native {ident}"></a><select aria-label="{ident} pose" onchange="const i=this.parentNode.querySelector('.shot');i.href=this.value;i.firstElementChild.src=this.value">{options}</select><p>{row['triangles']:,} triangles · {row['bones']} bones · {row['skinned_draws']} skin draws + 1 contact plane</p><p><a href="concepts/{ident}.png">Approved concept</a> · <a href="masters/{ident}.blend">Editable Blender master</a></p><details><summary>Clips</summary>{', '.join(row['clips'])}</details></article>''')
body=f'''<header><small>DEPTHS · #302 I · ACTUAL GODOT MOBILE CAPTURES</small><h1>Damp Caves creatures</h1><p>Four owner-approved concepts, four original rigged models, eight map/bestiary contours and eight companion reaction sounds. These scenes are ready for integration; enemy definitions, tactics, encounters and patrols remain caller-owned.</p><p>{report['checks']:,} native checks passed · {len(report['captures'])} captures · no owner saves or foreground changes. Phone views use warm torchlight; neutral views expose the shape.</p><p><a href="native/validation.json">Native measurements</a> · <a href="native-launch/launch.json">Private desktop record</a> · <a href="../local-damp-audio-v1/inspector.html">Sound listening desk</a></p></header><div class="grid">{''.join(cards)}</div><h2>Integration contract</h2><p>Metric floor origin, +Z front, two-metre tile. play / sample / set_motion / set_opacity / framing_bounds. All clips are authored at 24 fps. Base skin is opaque; only explicit ambient fades use the separate cached alpha shader. Submerge flattens under a caller-owned water surface; it grants no untargetability or hidden attack rule. The Mother uses the same clip names as the newt.</p><p>Original geometry reuses the project’s mesh/rig/floor-fitting helpers. No downloaded anatomy, private body or external animation. Generated concept sheets are preserved unchanged with exact prompts and hashes in the repository. Physical iPhone performance, owner model-style acceptance and live/exported combat hookup remain unverified.</p>'''
(creatures/'inspector.html').write_text(shell('Depths · Damp Caves creatures',body),encoding='utf-8')
sounds=read(ROOT/'audio/damp-caves-v1/catalog.json');pcm=read(audio/'pcm-validation.json');native=read(audio/'native-validation.json')
assert not pcm['failures'] and not native['failures']
(audio/'audio').mkdir(exist_ok=True);cards=[]
for row in sounds['assets']:
    file=Path(row['file']).name;shutil.copy2(ROOT/row['file'],audio/'audio'/file)
    cards.append(f'''<article><small>{row['category']}</small><h3>{row['label']}</h3><audio controls preload="none" {'loop' if row['loop'] else ''} src="audio/{file}"></audio><p>{row['seconds']:.2f}s · peak {row['peak_dbfs']:.1f} dBFS · {'seamless loop' if row['loop'] else 'one-shot'}</p><details><summary>Recipe and future hookup</summary><p>{html.escape(row['recipe'])}</p><p>{html.escape(row['hook'])}</p></details></article>''')
sources=''.join(f'<li><a href="{row["page"]}">{html.escape(row["title"])}</a> — {html.escape(row["author"])} · CC0</li>' for row in sounds['sources'])
body=f'''<header><small>DEPTHS · #302 H/I · LISTENING CANDIDATES</small><h1>Damp Caves sound desk</h1><p>Twelve environmental sounds and eight material-based creature reactions. Quiet sole contacts, distant water and sparse drips keep the mix restrained. These are new sounds, awaiting listening feedback and live assignment; existing music and {pcm['earlier_files']} earlier audio files are unchanged.</p><p>{pcm['checks']} PCM/provenance/rebuild checks + {native['checks']} native decoder/playback checks passed. Technical checks are not human listening approval.</p><p><a href="pcm-validation.json">PCM report</a> · <a href="native-validation.json">Muted native playback report</a> · <a href="../local-damp-creatures-v1/inspector.html">Creature gallery</a></p><h2>Short review reel</h2><audio controls preload="none" src="audition.wav"></audio><p>No autoplay. In-game ambience uses the existing −10 dB player gain; do not apply that gain twice. All files route to Effects; Music remains separate.</p></header><div class="grid">{''.join(cards)}</div><h2>Retained sources</h2><ul>{sources}</ul><p>Each source archive/recording, retained licence evidence and exact archive members are recorded in the repository catalogue. Water-pack HTML is byte-identical after text line-ending normalization. Reactions use wet material, shell clicks, balloon friction and shaped noise; they are not actor voices or claims of real animal recordings.</p><p>Headphone/physical-phone mix review and actual gameplay assignments remain. No audio or browser starts automatically.</p>'''
(audio/'inspector.html').write_text(shell('Depths · Damp Caves listening desk',body),encoding='utf-8')
print(creatures/'inspector.html');print(audio/'inspector.html')
